// ============================================================
// PAMMYS PRODUCT MATCHER — COMPLETE REPLACEMENT
// Deterministic matching only. The AI Agent only phrases replies.
// ============================================================

// ------------------------------------------------------------
// 1. REQUEST + DATA
// ------------------------------------------------------------
const request = $("Webhook").first().json.body || {};
const message = String(request.message || "").trim();
const locale = String(request.locale || "en").trim().toLowerCase();
const sessionId = request.session_id || null;
const rows = $input.all();

// ------------------------------------------------------------
// 2. NORMALIZATION + FUZZY HELPERS
// ------------------------------------------------------------
function normalize(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/ß/g, "ss")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/,/g, ".")
    .replace(/[’']/g, "")
    .replace(/[^a-z0-9/.+-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function tokenize(value) {
  return normalize(value)
    .split(" ")
    .map((token) => token.replace(/^[./+-]+|[./+-]+$/g, ""))
    .filter(Boolean);
}

function unique(values) {
  return [...new Set(values)];
}

function sortNatural(values) {
  return [...values].sort((a, b) =>
    String(a).localeCompare(String(b), undefined, {
      numeric: true,
      sensitivity: "base",
    })
  );
}

function editDistance(a, b) {
  a = normalize(a);
  b = normalize(b);

  const matrix = Array.from({ length: a.length + 1 }, () =>
    Array(b.length + 1).fill(0)
  );

  for (let i = 0; i <= a.length; i++) matrix[i][0] = i;
  for (let j = 0; j <= b.length; j++) matrix[0][j] = j;

  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;

      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,
        matrix[i][j - 1] + 1,
        matrix[i - 1][j - 1] + cost
      );

      if (
        i > 1 &&
        j > 1 &&
        a[i - 1] === b[j - 2] &&
        a[i - 2] === b[j - 1]
      ) {
        matrix[i][j] = Math.min(
          matrix[i][j],
          matrix[i - 2][j - 2] + 1
        );
      }
    }
  }

  return matrix[a.length][b.length];
}

function similarity(a, b) {
  a = normalize(a);
  b = normalize(b);

  if (!a || !b) return 0;
  if (a === b) return 1;

  const aNumber = /^\d+(?:\.\d+)?$/.test(a);
  const bNumber = /^\d+(?:\.\d+)?$/.test(b);

  if (aNumber || bNumber) {
    return a === b ? 1 : 0;
  }

  return 1 - editDistance(a, b) / Math.max(a.length, b.length);
}

function isStrongWordMatch(a, b) {
  a = normalize(a);
  b = normalize(b);

  if (!a || !b) return false;
  if (a === b) return true;

  const aNumber = /^\d+(?:\.\d+)?$/.test(a);
  const bNumber = /^\d+(?:\.\d+)?$/.test(b);

  if (aNumber || bNumber) {
    return a === b;
  }

  const minLength = Math.min(a.length, b.length);
  const distance = editDistance(a, b);

  if (minLength >= 4 && distance <= 1) {
    return true;
  }

  if (minLength >= 7 && distance <= 2) {
    return true;
  }

  if (
    minLength >= 5 &&
    (a.startsWith(b) || b.startsWith(a))
  ) {
    return true;
  }

  return false;
}

// ------------------------------------------------------------
// 3. PRODUCT TITLE PARSING
// Model - Color - Size, parsed from the right.
// ------------------------------------------------------------
const products = rows
  .map((item) => {
    const row = item.json || {};
    const title = String(row.product_title || "").trim();

    const parts = title
      .split(/\s+-\s+/)
      .map((part) => part.trim());

    if (parts.length < 3) {
      return null;
    }

    const size = parts.pop();
    const color = parts.pop();
    const model = parts.join(" - ");

    return {
      id: row.id,
      title,
      image_url: row.image_url || "",
      status: row.status || "",
      model,
      color,
      size,
    };
  })
  .filter(Boolean)
  .filter(
    (product) =>
      !product.status ||
      normalize(product.status) === "active"
  );

if (products.length === 0) {
  throw new Error(
    "No products were received from the Pammys Products Data Table."
  );
}

const q = normalize(message);
const queryTokens = tokenize(message);

const models = unique(
  products.map((product) => product.model)
);

// ------------------------------------------------------------
// 4. STOP WORDS
// ------------------------------------------------------------
const stopWords = new Set([
  // English
  "i",
  "im",
  "am",
  "want",
  "wanna",
  "would",
  "like",
  "looking",
  "look",
  "show",
  "find",
  "need",
  "give",
  "get",
  "have",
  "please",
  "me",
  "you",
  "for",
  "with",
  "in",
  "on",
  "of",
  "a",
  "an",
  "the",
  "pair",
  "product",
  "shoe",
  "shoes",
  "size",
  "color",
  "colour",

  // German
  "ich",
  "suche",
  "mochte",
  "moechte",
  "will",
  "bitte",
  "zeige",
  "mir",
  "mit",
  "fur",
  "fuer",
  "der",
  "die",
  "das",
  "ein",
  "eine",
  "farbe",
  "grosse",
  "groesse",
  "schuh",
  "schuhe",

  // French
  "je",
  "cherche",
  "veux",
  "voudrais",
  "montre",
  "moi",
  "avec",
  "pour",
  "de",
  "des",
  "du",
  "la",
  "le",
  "les",
  "couleur",
  "taille",
  "chaussure",
  "chaussures",

  // Spanish
  "yo",
  "busco",
  "quiero",
  "muestra",
  "con",
  "para",
  "de",
  "del",
  "la",
  "el",
  "los",
  "las",
  "color",
  "talla",
  "zapato",
  "zapatos",
]);

function isStopWord(token) {
  return stopWords.has(normalize(token));
}

// ------------------------------------------------------------
// 5. OUTPUT HELPERS
// ------------------------------------------------------------
function productPreview(list, limit = 30) {
  return list.slice(0, limit).map((product) => ({
    id: product.id,
    title: product.title,
    image_url: product.image_url,
    model: product.model,
    color: product.color,
    size: product.size,
  }));
}

function questionResult({
  questionKey,
  options,
  context,
  candidates = [],
  topCandidates = [],
}) {
  const preview = productPreview(candidates);

  return [
    {
      json: {
        type: questionKey,
        question_key: questionKey,

        options: Array.isArray(options)
          ? options
          : [],

        matched_candidates: preview,

        context: {
          ...context,

          matched_candidates: preview,

          ...(topCandidates.length
            ? {
                top_candidates:
                  topCandidates,
              }
            : {}),
        },
      },
    },
  ];
}

// ------------------------------------------------------------
// 6. SPECIFIC MODEL ALIASES
//
// IMPORTANT:
// Generic words such as "women", "mujer", "Damen",
// "men", "hombre" are NOT mapped directly to a model.
// ------------------------------------------------------------
const modelAliases = {
  "Snowboots 2.0": [
    "snow boots 2.0",
    "snowboot 2.0",
  ],

  "Originals Woman": [
    "original woman",
    "originals women",
  ],

  "Originals Men": [
    "original men",
    "originals man",
  ],

  "Step-Ins 3.0 Women": [
    "step ins 3.0 women",
    "stepins 3.0 women",
  ],

  "Step-Ins 3.0 Men": [
    "step ins 3.0 men",
    "stepins 3.0 men",
  ],

  "Step-Ins 3.0 Kids": [
    "step ins 3.0 kids",
    "stepins 3.0 kids",
  ],

  "Retro Sneaker 2.0": [
    "retro sneakers 2.0",
  ],
};

function phraseScore(query, phrase) {
  const qTokens = tokenize(query);
  const pTokens = tokenize(phrase);

  if (
    !qTokens.length ||
    !pTokens.length
  ) {
    return 0;
  }

  let total = 0;
  let matched = 0;

  for (const pToken of pTokens) {
    let best = 0;

    for (const qToken of qTokens) {
      const sim =
        similarity(pToken, qToken);

      if (
        isStrongWordMatch(
          pToken,
          qToken
        ) ||
        sim >= 0.76
      ) {
        best = Math.max(
          best,
          sim
        );
      }
    }

    if (best > 0) {
      matched++;
      total += best;
    }
  }

  const coverage =
    matched / pTokens.length;

  if (coverage < 0.7) {
    return 0;
  }

  return (
    (total / pTokens.length) *
      0.7 +
    coverage * 0.3
  );
}

// ------------------------------------------------------------
// 7. GENERIC GENDER / CATEGORY HINTS
//
// Generic gender terms restrict candidate models.
// They NEVER automatically choose "Originals Woman"
// or "Originals Men".
// ------------------------------------------------------------
const genderHints = {
  female: [
    // English
    "woman",
    "women",
    "womens",
    "lady",
    "ladies",
    "ladys",

    // German
    "dame",
    "damen",
    "damenschuh",
    "damenschuhe",
    "frau",
    "frauen",
    "frauenschuh",
    "frauenschuhe",

    // French
    "femme",
    "femmes",

    // Spanish
    "mujer",
    "mujeres",
  ],

  male: [
    // English
    "man",
    "men",
    "mens",

    // German
    "herr",
    "herren",
    "herrenschuh",
    "herrenschuhe",
    "mann",
    "manner",
    "mannerschuh",
    "mannerschuhe",

    // French
    "homme",
    "hommes",

    // Spanish
    "hombre",
    "hombres",
  ],
};

function hintMatches(
  queryToken,
  hint
) {
  // Spanish:
  // "dame" = "give me".
  //
  // Therefore singular "dame"
  // counts as a female word only
  // when selected locale = German.
  if (
    normalize(hint) === "dame" &&
    locale !== "de"
  ) {
    return false;
  }

  return (
    normalize(queryToken) ===
      normalize(hint) ||
    isStrongWordMatch(
      queryToken,
      hint
    )
  );
}

function detectGenderHint() {
  let female = 0;
  let male = 0;

  for (
    const queryToken of
      queryTokens
  ) {
    if (
      genderHints.female.some(
        (hint) =>
          hintMatches(
            queryToken,
            hint
          )
      )
    ) {
      female++;
    }

    if (
      genderHints.male.some(
        (hint) =>
          hintMatches(
            queryToken,
            hint
          )
      )
    ) {
      male++;
    }
  }

  if (
    female > 0 &&
    male === 0
  ) {
    return "female";
  }

  if (
    male > 0 &&
    female === 0
  ) {
    return "male";
  }

  if (female > male) {
    return "female";
  }

  if (male > female) {
    return "male";
  }

  return null;
}

function modelGender(
  candidateModel
) {
  const tokens =
    tokenize(candidateModel);

  const femaleMarkers =
    new Set([
      "woman",
      "women",
      "womens",
      "female",
      "lady",
      "ladies",
    ]);

  const maleMarkers =
    new Set([
      "man",
      "men",
      "mens",
      "male",
    ]);

  const isFemale =
    tokens.some(
      (token) =>
        femaleMarkers.has(token)
    );

  const isMale =
    tokens.some(
      (token) =>
        maleMarkers.has(token)
    );

  if (
    isFemale &&
    !isMale
  ) {
    return "female";
  }

  if (
    isMale &&
    !isFemale
  ) {
    return "male";
  }

  return null;
}

const genderHint =
  detectGenderHint();

// ------------------------------------------------------------
// 8. MODEL SCORING
// ------------------------------------------------------------
function scoreSpecificModel(
  candidateModel
) {
  const modelTokens =
    tokenize(candidateModel);

  const usefulQueryTokens =
    queryTokens.filter(
      (token) =>
        !isStopWord(token)
    );

  if (
    !modelTokens.length ||
    !usefulQueryTokens.length
  ) {
    return {
      score: 0,
      matched: 0,
      coverage: 0,
    };
  }

  let total = 0;
  let matched = 0;

  for (
    const modelToken of
      modelTokens
  ) {
    let best = 0;

    for (
      const queryToken of
        usefulQueryTokens
    ) {
      const sim =
        similarity(
          modelToken,
          queryToken
        );

      if (
        isStrongWordMatch(
          modelToken,
          queryToken
        ) ||
        sim >= 0.76
      ) {
        best = Math.max(
          best,
          sim
        );
      }
    }

    if (best > 0) {
      matched++;
      total += best;
    }
  }

  const coverage =
    matched /
    modelTokens.length;

  const average =
    matched
      ? total / matched
      : 0;

  const score =
    average * 0.65 +
    coverage * 0.35;

  return {
    score,
    matched,
    coverage,
  };
}

let model = null;

// ------------------------------------------------------------
// A. EXACT MODEL
// ------------------------------------------------------------
const exactModelMatches =
  models
    .filter(
      (candidateModel) =>
        q.includes(
          normalize(
            candidateModel
          )
        )
    )
    .sort(
      (a, b) =>
        normalize(b).length -
        normalize(a).length
    );

if (
  exactModelMatches.length
) {
  model =
    exactModelMatches[0];
}

// ------------------------------------------------------------
// B. SPECIFIC ALIASES
// ------------------------------------------------------------
if (!model) {
  const aliasMatches = [];

  for (
    const [
      targetModel,
      aliases,
    ] of Object.entries(
      modelAliases
    )
  ) {
    if (
      !models.includes(
        targetModel
      )
    ) {
      continue;
    }

    let bestScore = 0;

    for (
      const alias of aliases
    ) {
      bestScore =
        Math.max(
          bestScore,
          phraseScore(
            message,
            alias
          )
        );
    }

    if (
      bestScore >= 0.78
    ) {
      aliasMatches.push({
        model: targetModel,
        score: bestScore,
      });
    }
  }

  aliasMatches.sort(
    (a, b) =>
      b.score - a.score
  );

  if (
    aliasMatches.length &&
    (
      !aliasMatches[1] ||
      aliasMatches[0].score -
        aliasMatches[1].score >=
        0.07
    )
  ) {
    model =
      aliasMatches[0].model;
  }
}

// ------------------------------------------------------------
// C. STRONG FUZZY SPECIFIC MODEL
//
// Generic "women" must NOT choose one specific
// female model.
//
// But:
// "Orignals Womam"
// SHOULD choose Originals Woman.
// ------------------------------------------------------------
if (!model) {
  const scored =
    models
      .map(
        (
          candidateModel
        ) => ({
          model:
            candidateModel,

          ...scoreSpecificModel(
            candidateModel
          ),
        })
      )
      .sort(
        (a, b) =>
          b.score - a.score
      );

  const strong =
    scored.filter(
      (item) => {
        const tokenCount =
          tokenize(
            item.model
          ).length;

        // Single-token models:
        // Hugy -> Huggy
        if (
          tokenCount === 1
        ) {
          return (
            item.matched >= 1 &&
            item.score >= 0.82
          );
        }

        // Multi-token models require
        // at least two matching model words.
        return (
          item.matched >= 2 &&
          item.coverage >= 0.66 &&
          item.score >= 0.78
        );
      }
    );

  if (
    strong.length &&
    (
      !strong[1] ||
      strong[0].score -
        strong[1].score >=
        0.06
    )
  ) {
    model =
      strong[0].model;
  }
}

// ------------------------------------------------------------
// D. GENERIC WOMEN / MEN REQUEST
//
// Now, only after trying to identify a SPECIFIC model,
// use gender/category information.
// ------------------------------------------------------------
if (
  !model &&
  genderHint
) {
  const genderModels =
    models.filter(
      (candidateModel) =>
        modelGender(
          candidateModel
        ) === genderHint
    );

  if (
    genderModels.length === 1
  ) {
    model =
      genderModels[0];
  } else if (
    genderModels.length > 1
  ) {
    const candidates =
      products.filter(
        (product) =>
          genderModels.includes(
            product.model
          )
      );

    return questionResult({
      questionKey:
        "ambiguous_model",

      options:
        sortNatural(
          genderModels
        ).map(
          (name) => ({
            model: name,
          })
        ),

      context: {
        locale,
        session_id:
          sessionId,

        original_message:
          message,

        category_hint:
          genderHint,
      },

      candidates,

      topCandidates:
        productPreview(
          candidates,
          10
        ),
    });
  }
}

// ------------------------------------------------------------
// E. GENERAL FUZZY MODEL MATCHING
// ------------------------------------------------------------
if (!model) {
  const scoredModels =
    models
      .map(
        (
          candidateModel
        ) => ({
          model:
            candidateModel,

          ...scoreSpecificModel(
            candidateModel
          ),
        })
      )
      .sort(
        (a, b) =>
          b.score - a.score
      );

  const best =
    scoredModels[0];

  const second =
    scoredModels[1];

  if (
    best &&
    best.score >= 0.72 &&
    best.coverage >= 0.5 &&
    (
      !second ||
      best.score -
        second.score >=
        0.08
    )
  ) {
    model = best.model;
  } else {
    const bestScore =
      best?.score || 0;

    let plausible =
      scoredModels.filter(
        (item) =>
          item.score >= 0.35 &&
          item.score >=
            bestScore - 0.12
      );

    if (
      !plausible.length
    ) {
      plausible =
        scoredModels.slice(
          0,
          6
        );
    }

    plausible =
      plausible.slice(
        0,
        8
      );

    const names =
      plausible.map(
        (item) =>
          item.model
      );

    const candidates =
      products.filter(
        (product) =>
          names.includes(
            product.model
          )
      );

    return questionResult({
      questionKey:
        "ambiguous_model",

      options:
        plausible.map(
          (item) => ({
            model:
              item.model,

            score:
              Number(
                item.score.toFixed(
                  2
                )
              ),
          })
        ),

      context: {
        locale,

        session_id:
          sessionId,

        original_message:
          message,
      },

      candidates,

      topCandidates:
        productPreview(
          candidates,
          10
        ),
    });
  }
}

// ------------------------------------------------------------
// 9. FILTER PRODUCTS BY SELECTED MODEL
// ------------------------------------------------------------
const modelProducts =
  products.filter(
    (product) =>
      product.model ===
      model
  );

const colors =
  unique(
    modelProducts.map(
      (product) =>
        product.color
    )
  );

// ------------------------------------------------------------
// 10. MULTILINGUAL COLOR ALIASES
// ------------------------------------------------------------
const colorAliases = {
  black: [
    "black",
    "schwarz",
    "noir",
    "negro",
    "negra",
  ],

  white: [
    "white",
    "weiss",
    "blanc",
    "blanche",
    "blanco",
    "blanca",
  ],

  grey: [
    "grey",
    "gray",
    "grau",
    "gris",
  ],

  blue: [
    "blue",
    "blau",
    "bleu",
    "azul",
  ],

  green: [
    "green",
    "grun",
    "gruen",
    "vert",
    "verde",
  ],

  red: [
    "red",
    "rot",
    "rouge",
    "rojo",
    "roja",
  ],

  pink: [
    "pink",
    "rosa",
    "rose",
  ],

  brown: [
    "brown",
    "braun",
    "marron",
  ],

  purple: [
    "purple",
    "violet",
    "lila",
    "morado",
    "morada",
  ],

  yellow: [
    "yellow",
    "gelb",
    "jaune",
    "amarillo",
    "amarilla",
  ],

  orange: [
    "orange",
  ],

  beige: [
    "beige",
  ],
};

function canonicalColorWord(
  word
) {
  const normalized =
    normalize(word);

  for (
    const [
      canonical,
      aliases,
    ] of Object.entries(
      colorAliases
    )
  ) {
    if (
      aliases.some(
        (alias) =>
          normalize(alias) ===
            normalized ||
          isStrongWordMatch(
            alias,
            normalized
          )
      )
    ) {
      return canonical;
    }
  }

  return normalized;
}

function colorWordSimilarity(
  a,
  b
) {
  return similarity(
    canonicalColorWord(a),
    canonicalColorWord(b)
  );
}

function colorWordMatches(
  a,
  b
) {
  return isStrongWordMatch(
    canonicalColorWord(a),
    canonicalColorWord(b)
  );
}

// ------------------------------------------------------------
// Remove model/gender/filler words before searching for color.
// ------------------------------------------------------------
const modelTokens =
  tokenize(model);

const allAliasTokens =
  Object.values(
    modelAliases
  )
    .flat()
    .flatMap(
      (alias) =>
        tokenize(alias)
    );

const allGenderTokens =
  Object.values(
    genderHints
  )
    .flat()
    .flatMap(
      (hint) =>
        tokenize(hint)
    );

const possibleColorInputTokens =
  queryTokens.filter(
    (queryToken) => {
      if (
        isStopWord(
          queryToken
        )
      ) {
        return false;
      }

      if (
        /^\d+(?:\.\d+)?$/.test(
          queryToken
        )
      ) {
        return false;
      }

      const modelWord =
        modelTokens.some(
          (modelToken) =>
            isStrongWordMatch(
              queryToken,
              modelToken
            )
        );

      if (modelWord) {
        return false;
      }

      const aliasWord =
        allAliasTokens.some(
          (aliasToken) =>
            isStrongWordMatch(
              queryToken,
              aliasToken
            )
        );

      if (aliasWord) {
        return false;
      }

      const genderWord =
        allGenderTokens.some(
          (genderToken) =>
            hintMatches(
              queryToken,
              genderToken
            )
        );

      if (genderWord) {
        return false;
      }

      return true;
    }
  );

// ------------------------------------------------------------
// 11. COLOR MATCHING
// ------------------------------------------------------------
let color = null;

// A. Exact complete color phrase.
const exactColors =
  colors
    .filter(
      (
        candidateColor
      ) =>
        q.includes(
          normalize(
            candidateColor
          )
        )
    )
    .sort(
      (a, b) =>
        normalize(b).length -
        normalize(a).length
    );

if (
  exactColors.length
) {
  color =
    exactColors[0];
}

// B. Fuzzy color matching.
if (!color) {
  const scoredColors =
    colors
      .map(
        (
          candidateColor
        ) => {
          const candidateTokens =
            tokenize(
              candidateColor
            );

          let matched = 0;
          let total = 0;

          for (
            const candidateToken of
              candidateTokens
          ) {
            let best = 0;

            for (
              const queryToken of
                possibleColorInputTokens
            ) {
              const sim =
                colorWordSimilarity(
                  candidateToken,
                  queryToken
                );

              if (
                colorWordMatches(
                  candidateToken,
                  queryToken
                ) ||
                sim >= 0.76
              ) {
                best =
                  Math.max(
                    best,
                    sim
                  );
              }
            }

            if (best > 0) {
              matched++;
              total += best;
            }
          }

          const coverage =
            candidateTokens.length
              ? matched /
                candidateTokens.length
              : 0;

          const average =
            matched
              ? total / matched
              : 0;

          const score =
            average * 0.7 +
            coverage * 0.3;

          return {
            color:
              candidateColor,

            score,
            coverage,
            matched,
          };
        }
      )
      .filter(
        (item) =>
          item.matched > 0 &&
          item.coverage >= 0.5
      )
      .sort(
        (a, b) =>
          b.score - a.score
      );

  const best =
    scoredColors[0];

  if (
    best &&
    best.score >= 0.77
  ) {
    const close =
      scoredColors.filter(
        (item) =>
          item.score >=
          best.score - 0.06
      );

    if (
      close.length === 1
    ) {
      color =
        best.color;
    } else {
      const options =
        sortNatural(
          unique(
            close.map(
              (item) =>
                item.color
            )
          )
        );

      const candidates =
        modelProducts.filter(
          (product) =>
            options.includes(
              product.color
            )
        );

      return questionResult({
        questionKey:
          "missing_color",

        options,

        context: {
          model,
          locale,

          session_id:
            sessionId,

          original_message:
            message,

          color_hint:
            possibleColorInputTokens.join(
              " "
            ),
        },

        candidates,
      });
    }
  }
}

// C. No color was provided / recognized.
if (!color) {
  if (
    colors.length === 1
  ) {
    color =
      colors[0];
  } else {
    return questionResult({
      questionKey:
        "missing_color",

      options:
        sortNatural(
          colors
        ),

      context: {
        model,
        locale,

        session_id:
          sessionId,

        original_message:
          message,
      },

      candidates:
        modelProducts,
    });
  }
}

// ------------------------------------------------------------
// 12. FILTER MODEL + COLOR
// ------------------------------------------------------------
const colorProducts =
  modelProducts.filter(
    (product) =>
      product.color ===
      color
  );

const sizes =
  unique(
    colorProducts.map(
      (product) =>
        product.size
    )
  );

// ------------------------------------------------------------
// 13. SIZE HELPERS
// ------------------------------------------------------------
function extractNumbers(
  value
) {
  return (
    String(value || "")
      .match(
        /\d+(?:[.,]\d+)?/g
      )
      ?.map(
        (number) =>
          number.replace(
            ",",
            "."
          )
      ) || []
  );
}

function numbersInSize(
  sizeLabel
) {
  return extractNumbers(
    sizeLabel
  );
}

// English: size
// German: Größe / Groesse
// French: taille
// Spanish: talla
const explicitSizeRegex =
  /\b(size|grosse|groesse|taille|talla)\b\s*(?:is\s*)?([a-z0-9./+-]+)/i;

const explicitSizeMatch =
  q.match(
    explicitSizeRegex
  );

const explicitRequestedSize =
  explicitSizeMatch
    ? explicitSizeMatch[2]
    : null;

let size = null;

// ------------------------------------------------------------
// A. EXACT EXPLICIT SIZE
// ------------------------------------------------------------
if (
  explicitRequestedSize
) {
  size =
    sizes.find(
      (catalogSize) =>
        normalize(
          catalogSize
        ) ===
        normalize(
          explicitRequestedSize
        )
    );
}

// ------------------------------------------------------------
// B. EXACT GROUPED SIZE
//
// Example:
// 40/41
// ------------------------------------------------------------
if (!size) {
  const grouped =
    sizes.filter(
      (catalogSize) =>
        normalize(
          catalogSize
        ).includes("/") &&
        q.includes(
          normalize(
            catalogSize
          )
        )
    );

  if (
    grouped.length === 1
  ) {
    size =
      grouped[0];
  }
}

// ------------------------------------------------------------
// C. SMART NUMERIC SIZE
//
// User: 39
// Catalog: 38/39
// ------------------------------------------------------------
if (!size) {
  let requestedNumbers =
    explicitRequestedSize
      ? extractNumbers(
          explicitRequestedSize
        )
      : [];

  if (
    !requestedNumbers.length
  ) {
    const messageNumbers =
      extractNumbers(
        message
      );

    const modelNumbers =
      extractNumbers(
        model
      );

    requestedNumbers =
      messageNumbers.filter(
        (number) =>
          !modelNumbers.includes(
            number
          )
      );
  }

  if (
    requestedNumbers.length
  ) {
    const matchingSizes =
      sizes.filter(
        (catalogSize) => {
          const availableNumbers =
            numbersInSize(
              catalogSize
            );

          return (
            requestedNumbers.some(
              (requested) =>
                availableNumbers.includes(
                  requested
                )
            )
          );
        }
      );

    if (
      matchingSizes.length ===
      1
    ) {
      size =
        matchingSizes[0];
    } else if (
      matchingSizes.length >
      1
    ) {
      const options =
        sortNatural(
          matchingSizes
        );

      return questionResult({
        questionKey:
          "missing_size",

        options,

        context: {
          model,
          color,
          locale,

          session_id:
            sessionId,

          original_message:
            message,

          requested_size:
            explicitRequestedSize ||
            requestedNumbers.join(
              ", "
            ),
        },

        candidates:
          colorProducts.filter(
            (product) =>
              options.includes(
                product.size
              )
          ),
      });
    }
  }
}

// ------------------------------------------------------------
// D. TEXT SIZES: S / M / L / XL etc.
// ------------------------------------------------------------
if (
  !size &&
  explicitRequestedSize
) {
  const requested =
    normalize(
      explicitRequestedSize
    );

  const textMatches =
    sizes.filter(
      (catalogSize) =>
        normalize(
          catalogSize
        ) === requested
    );

  if (
    textMatches.length ===
    1
  ) {
    size =
      textMatches[0];
  }
}

// ------------------------------------------------------------
// E. MISSING SIZE
// ------------------------------------------------------------
if (!size) {
  if (
    sizes.length === 1
  ) {
    size =
      sizes[0];
  } else {
    return questionResult({
      questionKey:
        "missing_size",

      options:
        sortNatural(
          sizes
        ),

      context: {
        model,
        color,
        locale,

        session_id:
          sessionId,

        original_message:
          message,

        requested_size:
          explicitRequestedSize ||
          null,
      },

      candidates:
        colorProducts,
    });
  }
}

// ------------------------------------------------------------
// 14. FINAL EXACT PRODUCT VARIANT
// ------------------------------------------------------------
const exactProducts =
  colorProducts.filter(
    (product) =>
      product.size ===
      size
  );

if (
  !exactProducts.length
) {
  return questionResult({
    questionKey:
      "missing_size",

    options:
      sortNatural(
        sizes
      ),

    context: {
      model,
      color,
      locale,

      session_id:
        sessionId,

      original_message:
        message,
    },

    candidates:
      colorProducts,
  });
}

const product =
  exactProducts[0];

// ------------------------------------------------------------
// 15. SUCCESS
// ------------------------------------------------------------
return [
  {
    json: {
      type: "match",

      product: {
        id:
          product.id,

        title:
          product.title,

        image_url:
          product.image_url,
      },

      context: {
        model,
        color,
        size,
        locale,

        session_id:
          sessionId,

        original_message:
          message,
      },

      matched_candidates: [
        {
          id:
            product.id,

          title:
            product.title,

          image_url:
            product.image_url,

          model:
            product.model,

          color:
            product.color,

          size:
            product.size,
        },
      ],
    },
  },
];

